<section class="panel"><div class="admin-heading"><h2><?= e($o['reference']) ?></h2><span><?= e($o['created_at']) ?> UTC</span></div><div class="order-detail-grid"><div><h3>Customer</h3><p><?= e($o['customer_name']) ?><br><?= e($o['email']) ?><br><?= e($o['phone']) ?></p><h3>Delivery</h3><p><?= nl2br(e($o['address'])) ?><br><?= e($o['city']) ?></p><?php $deliveryOrder=$o;require ROOT.'/app/views/delivery-order.php'; ?><h3>Customer notes</h3><p><?= e($o['notes']?:'No notes') ?></p></div><div><h3>Chosen pieces</h3><?php foreach(rows('SELECT * FROM order_items WHERE order_id=?',[$o['id']]) as $item): ?><div class="summary-line order-item-line"><span class="thumbnail-label"><img class="item-thumbnail" src="<?= e(image_url($item['image']?:'/assets/favicon.svg')) ?>" alt="<?= e($item['product_name']) ?>" loading="lazy" width="56" height="64"><span><?= e($item['product_name']) ?> × <?= (int)$item['quantity'] ?><?php require ROOT.'/app/views/order-item-variant.php'; ?></span></span><strong><?= e($o['currency']) ?> <?= number_format(($item['final_line_total']??$item['unit_price']*$item['quantity'])/100,2) ?></strong></div><?php endforeach ?><div class="summary-line"><span>Product subtotal</span><span><?= e($o['currency']) ?> <?= number_format($o['subtotal']/100,2) ?></span></div><?php $discountOrder=$o;require ROOT.'/app/views/order-discount.php'; ?><div class="summary-line"><span>Delivery</span><span><?= e($o['currency']) ?> <?= number_format($o['delivery_fee']/100,2) ?></span></div><div class="summary-line"><span>Tax</span><span><?= e($o['currency']) ?> <?= number_format($o['tax']/100,2) ?></span></div><div class="summary-line"><strong>Total</strong><strong><?= e($o['currency']) ?> <?= number_format($o['total']/100,2) ?></strong></div></div></div><form method="post" action="/admin/orders"><?= csrf_field() ?><input type="hidden" name="section" value="orders"><input type="hidden" name="action" value="order"><input type="hidden" name="id" value="<?= e($o['id']) ?>"><div class="form-grid"><label>Order status<select name="status" data-order-status-control data-order-status="<?= e($o['status']) ?>"><?php foreach(ORDER_STATUSES as $status): ?><option value="<?= $status ?>" <?= $o['status']===$status?'selected':'' ?>><?= e(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach ?></select></label><label>Payment status<select name="payment_status"><?php foreach(['unpaid','paid','refunded'] as $status): ?><option <?= $o['payment_status']===$status?'selected':'' ?>><?= $status ?></option><?php endforeach ?></select></label><label class="span-2">Internal notes<textarea name="internal_notes" rows="4" maxlength="5000"><?= e($o['internal_notes']) ?></textarea></label></div><p class="muted">Cancelling an order restores its stock once. Cancelled or completed orders cannot be reopened.</p><button class="button" data-order-save data-order-status="<?= e($o['status']) ?>">Save order</button></form></section>
<?php endif ?>
<form method="get" class="filter-bar" action="/admin/orders"><label>Search orders<input name="q" value="<?= e($_GET['q']??'') ?>" placeholder="Reference, name, email"></label><label>Status<select name="status" data-order-status-control data-order-status="<?= e($_GET['status']??'') ?>"><option value="">All statuses</option><?php foreach(ORDER_STATUSES as $status): ?><option value="<?= $status ?>" <?= ($_GET['status']??'')===$status?'selected':'' ?>><?= e(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach ?></select></label><button class="button">Filter</button></form>
<?php $where=['1=1'];$args=[];$search=text_input($_GET,'q',160);if($search){$where[]='(reference LIKE ? OR customer_name LIKE ? OR email LIKE ?)';$args=["%$search%","%$search%","%$search%"];}if(!empty($_GET['status'])){$where[]='status=?';$args[]=text_input($_GET,'status',30);} $orders=rows('SELECT orders.*, (SELECT image FROM order_items WHERE order_id=orders.id ORDER BY id LIMIT 1) AS thumbnail FROM orders WHERE '.implode(' AND ',$where).' ORDER BY created_at DESC',$args); ?>
<div class="panel table-scroll"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Created (UTC)</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><div class="thumbnail-label"><img class="item-thumbnail" src="<?= e(image_url($o['thumbnail']?:'/assets/favicon.svg')) ?>" alt="" loading="lazy" width="56" height="64"><span><?= e($o['reference']) ?><?php if(!empty($o['delivery_governorate'])): ?><small><?= e(lebanon_governorates()[$o['delivery_governorate']]['en']??$o['delivery_governorate']) ?></small><?php endif ?></span></div></td><td><?= e($o['customer_name']) ?><small><?= e($o['email']) ?></small></td><td><?= e($o['currency']) ?> <?= number_format($o['total']/100,2) ?></td><td><span class="status-tag" data-order-status="<?= e($o['status']) ?>"><?= e(ucwords(str_replace('_',' ',$o['status']))) ?></span></td><td><?= e($o['created_at']) ?></td><td><a class="text-link" href="/admin/orders?view=<?= e($o['id']) ?>">View order</a></td></tr><?php endforeach ?></tbody></table><?php if(!$orders): ?><p class="empty-state">No orders found.</p><?php endif ?></div>
